import {DEFAULTS,calculate,money} from './pricing.js';
import {prepareDraft,sendDraft,acceptQuote,requestChange,approveChange,addMessage,markViewed,confirmBooking,statusLabel} from './journey.js';
const enquiryOnly=new URLSearchParams(location.search||'').get('view')==='enquiry';
document.documentElement.classList.toggle('enquiry-only',enquiryOnly);
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let settings={...DEFAULTS};
try{const saved=JSON.parse(localStorage.getItem('valet-rates-v1'));if(saved)for(const k of Object.keys(DEFAULTS))if(Number.isFinite(saved[k])&&saved[k]>=0)settings[k]=saved[k];}catch{}
const access=()=>({service:'ready',floor:'0',lift:'yes',steps:'none',carry:'near',parking:'yes',tight:false});
const blank=()=>({from:'',to:'',date:'',flexible:true,timing:'standard',stops:[],description:'',load:'small',itemKind:'unknown',assembly:'no',listing:'',pickup:access(),dropoff:access(),name:'',email:'',phone:'',notes:'',whatsapp:false,acknowledge:false});
let job=blank(),photos=[],step=0,records=[],selectedId=null,customerRecordId=null,toastTimer;
const labels={load:{small:'1â€“3 items / a few boxes',medium:'A small move / part van',large:'A larger move / full van',unknown:'Load to confirm'},itemKind:{light:'Manageable boxes / light items',bulky:'Standard bulky furniture',special:'Unusually heavy / fragile',unknown:'Handling to confirm'},service:{ready:'Ready at ground-floor entrance',indoor:'Indoor help',unsure:'Service to confirm'},carry:{near:'Under 10m',mid:'10â€“30m',long:'30â€“50m',far:'Over 50m',unknown:'Distance unknown'}};
function get(path,obj=job){return path.split('.').reduce((a,k)=>a?.[k],obj);}
function put(path,value,obj=job){const keys=path.split('.');let t=obj;keys.slice(0,-1).forEach(k=>t=t[k]);t[keys.at(-1)]=value;}
function input(name,label,type='text',placeholder='',extra=''){return `<label class="field"><span class="field-label">${label}</span><input name="${name}" type="${type}" value="${esc(get(name))}" placeholder="${esc(placeholder)}" ${extra}></label>`;}
function select(name,label,options){return `<label class="field"><span class="field-label">${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${v}" ${String(get(name))===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function check(name,label){return `<label class="check"><input type="checkbox" name="${name}" ${get(name)?'checked':''}><span>${label}</span></label>`;}
function choices(name,label,options){return `<fieldset><legend>${label}</legend><div class="choice-row">${options.map(([v,t,d])=>`<label class="choice"><input type="radio" name="${name}" value="${v}" ${get(name)===v?'checked':''}><span>${t}${d?`<small>${d}</small>`:''}</span></label>`).join('')}</div></fieldset>`;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function goView(owner){if(enquiryOnly)owner=false;$('#deliveryView').hidden=true;$('#screensTab').classList.remove('active');$('#screensTab').setAttribute('aria-pressed','false');$('#customerView').hidden=owner;$('#ownerView').hidden=!owner;$('#customerTab').classList.toggle('active',!owner);$('#ownerTab').classList.toggle('active',owner);$('#customerTab').setAttribute('aria-pressed',String(!owner));$('#ownerTab').setAttribute('aria-pressed',String(owner));if(owner){renderQueue();renderDetail();}window.scrollTo({top:0,behavior:'smooth'});}
$('#customerTab').onclick=()=>goView(false);$('#ownerTab').onclick=()=>goView(true);$('#footerOwner').onclick=()=>goView(true);
document.querySelectorAll('header a').forEach(a=>a.addEventListener('click',()=>{if(!$('#ownerView').hidden||!$('#deliveryView').hidden)goView(false);}));
function capture(){for(const e of $('#formStep').querySelectorAll('[name]')){if(e.type==='radio'&&!e.checked)continue;if(e.type==='file')continue;if(e.name.startsWith('stop-')){job.stops[Number(e.name.slice(5))]=e.value;continue;}put(e.name,e.type==='checkbox'?e.checked:e.value);}}
function renderStep(){
 $('#formError').hidden=true;
 document.querySelectorAll('.stepper li').forEach((li,i)=>{li.classList.toggle('active',i===step);li.classList.toggle('done',i<step);if(i===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});
 $('#backBtn').hidden=step===0;$('#nextBtn').innerHTML=step===2?'Request my quote <span>â†—</span>':'Continue <span>â†’</span>';
 if(step===0)$('#formStep').innerHTML=`<div class="route-fields">${input('from','Collection address or Eircode','text','e.g. Sandyford, Dublin 18','autocomplete="off" maxlength="180"')}${input('to','Delivery address or Eircode','text','e.g. Bray, Co. Wicklow','autocomplete="off" maxlength="180"')}</div><div id="extraStops">${job.stops.map((s,i)=>`<div class="stop-row"><input aria-label="Extra stop ${i+1}" name="stop-${i}" value="${esc(s)}" placeholder="Extra stop address or Eircode" maxlength="180"><button type="button" class="textbutton" data-remove-stop="${i}">Remove</button></div>`).join('')}</div><button type="button" class="textbutton" id="addStop">+ Add another stop</button><div class="two-col">${input('date','Preferred moving date','date','','min="'+new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Dublin'})+'"')}${select('timing','Timing',[['standard','Standard daytime'],['urgent','Urgent / out of hours']])}</div>${check('flexible','My date is flexible â€” a suitable route slot could cost less.')}<p class="soft-note">An area or Eircode is enough to get started. Weâ€™ll confirm the exact addresses and route before quoting.</p>`;
 if(step===1)$('#formStep').innerHTML=`<label class="field"><span class="field-label">What are we moving?</span><textarea name="description" maxlength="2500" rows="3" placeholder="e.g. One 3-seater sofa, a dismantled double bed and 8 packed boxes. Add dimensions or weight if known.">${esc(job.description)}</textarea><small>A short description is perfect. No item-by-item inventory required.</small></label>${select('load','Roughly how much is there?',Object.entries(labels.load))}${select('itemKind','What best describes the items?',Object.entries(labels.itemKind))}${select('assembly','Will anything need dismantling or reassembly?',[['no','No â€” everything will be ready'],['yes','Yes â€” please include this'],['unknown','Not sure yet']])}<label class="upload">Add a few photos <span class="muted">(optional)</span><input id="photoInput" type="file" accept="image/jpeg,image/png,image/webp" multiple><span class="helper">Up to 5 JPG, PNG or WebP photos, 10 MB each. Previewed in this tab only.</span></label><div id="photos" class="photos"></div>${input('listing','Or paste an item listing link (optional)','url','https://â€¦','maxlength="2000"')}<p class="helper">For bulky or unusual items, photos and dimensions help us confirm a suitable crew.</p>`;
 if(step===2)$('#formStep').innerHTML=`<p class="helper">Choose the help you need at <strong>both</strong> addresses. Select â€œNot sureâ€ whenever you need us to check.</p>${accessCard('pickup','Collection',job.from)}${accessCard('dropoff','Delivery',job.to)}<div class="subhead">Where should we send your quote?</div>${input('name','Your name','text','Full name','autocomplete="name" maxlength="100"')}<div class="two-col">${input('phone','Phone number','tel','Your number','autocomplete="tel" maxlength="40"')}${input('email','Email address (required)','email','you@example.com','autocomplete="email" maxlength="180"')}</div>${check('whatsapp','Also send my quote and updates about this move by WhatsApp.')}<p class="helper">Your quote will be sent by email. Add your phone number if you choose WhatsApp too.</p><label class="field"><span class="field-label">Anything else we should know? <span class="muted">(optional)</span></span><textarea name="notes" rows="2" maxlength="2000" placeholder="Collection times, access arrangements or anything that might helpâ€¦">${esc(job.notes)}</textarea></label>${check('acknowledge','Iâ€™ve checked both addresses as best I can. I understand the price and job details will be confirmed before booking.')}<p class="soft-note">Working model: this request stays in this browser tab. No message is sent and no booking is made.</p>`;
 if(step===1)renderPhotos();
 $('#formStep').querySelectorAll('[name]').forEach(el=>{el.addEventListener('input',capture);el.addEventListener('change',()=>{capture();if(el.name.endsWith('.service')||el.name.endsWith('.floor'))renderStep();});});
 $('#addStop')?.addEventListener('click',()=>{capture();if(job.stops.length>=3)return toast('For more than 3 extra stops, add the details in your notes.');job.stops.push('');renderStep();});
 document.querySelectorAll('[data-remove-stop]').forEach(b=>b.onclick=()=>{capture();job.stops.splice(Number(b.dataset.removeStop),1);renderStep();});
 $('#photoInput')?.addEventListener('change',e=>{let errors=[];for(const f of e.target.files){if(photos.length>=5){errors.push('Maximum 5 photos.');break;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)){errors.push('Use JPG, PNG or WebP.');continue;}if(f.size>10*1024*1024){errors.push('Each photo must be under 10 MB.');continue;}photos.push({name:f.name,url:URL.createObjectURL(f)});}if(errors.length)toast([...new Set(errors)].join(' '));renderPhotos();e.target.value='';});
}
function accessCard(key,title,address){const a=job[key];return `<section class="address-card"><div class="address-head"><strong>${title}</strong><span>${esc(address)}</span></div><div class="address-body">${choices(key+'.service','Where do you need our help?',[['ready','Ready at entrance','Ground floor, packed and ready'],['indoor','Inside the property','From / to a room or upstairs'],['unsure','Not sure','Please help me decide']])}${a.service==='ready'?'<p class="helper">Standard entrance service assumes level access, no steps and the vehicle within 10 metres. Different access will be reviewed.</p>':''}${a.service==='indoor'?`<div class="two-col">${select(key+'.floor','Which floor?',[['0','Ground floor'],['1','First floor'],['2','Second floor'],['3','Third floor'],['4','Fourth floor'],['5','Fifth floor'],['unknown','Not sure / multiple floors']])}${Number(a.floor)>0?select(key+'.lift','Lift fits all items?',[['yes','Yes â€” suitable lift'],['no','No â€” use the stairs'],['unknown','Not sure']]):''}</div>`:''}<div class="two-col">${select(key+'.steps','Steps outside?',[['none','No steps'],['few','1â€“3 steps'],['many','4 or more steps'],['unknown','Not sure']])}${select(key+'.carry','Vehicle to entrance',Object.entries(labels.carry))}</div>${select(key+'.parking','Can the vehicle stop safely and legally?',[['yes','Yes â€” loading access available'],['no','No â€” access is difficult'],['unknown','Not sure']])}${check(key+'.tight','Narrow doors, tight turns or other awkward access')}</div></section>`;}
function renderPhotos(){const p=$('#photos');if(!p)return;p.innerHTML=photos.map((f,i)=>`<div class="photo"><img src="${f.url}" alt="Preview of ${esc(f.name)}"><button type="button" aria-label="Remove ${esc(f.name)}" data-photo="${i}">Ã—</button><span>${esc(f.name)}</span></div>`).join('');p.querySelectorAll('button').forEach(b=>b.onclick=()=>{URL.revokeObjectURL(photos[Number(b.dataset.photo)].url);photos.splice(Number(b.dataset.photo),1);renderPhotos();});}
function validation(){if(step===0){if(job.from.trim().length<3||job.to.trim().length<3)return 'Please add the collection and delivery locations.';if(!job.flexible&&!job.date)return 'Choose a preferred date, or select â€œMy date is flexibleâ€.';if(job.date&&job.date<new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Dublin'}))return 'Please choose today or a future date.';if(job.stops.some(x=>x.trim().length<3))return 'Please complete each extra stop or remove it.';}if(step===1){if(job.description.trim().length<10)return 'Please add a short description of what needs moving.';if(job.listing&&!/^https?:\/\/[^\s]+$/i.test(job.listing))return 'Please use a full listing link beginning with https:// or http://.';}if(step===2){if(job.name.trim().length<2)return 'Please add your name.';if(!job.email.trim())return 'Please provide an email address for your quote.';if(job.whatsapp&&!job.phone.trim())return 'Please add a phone number for WhatsApp updates.';if(job.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(job.email))return 'Please check the email address.';if(job.phone&&job.phone.replace(/\D/g,'').length<7)return 'Please check the phone number.';if(!job.acknowledge)return 'Please confirm that you have checked the details before continuing.';}return '';}
$('#quoteForm').addEventListener('submit',e=>{e.preventDefault();capture();const error=validation();if(error){$('#formError').textContent=error;$('#formError').hidden=false;return;}if(step<2){step++;renderStep();$('#quote').scrollIntoView({behavior:'smooth',block:'start'});}else submitJob();});
$('#backBtn').onclick=()=>{capture();step--;renderStep();$('#quote').scrollIntoView({behavior:'smooth',block:'start'});};
function submitJob(){const id='VLT-'+String(records.length+1).padStart(3,'0');records.unshift({id,job:clone(job),photos:[...photos],overrides:{},confirmed:null,isSample:false});selectedId=id;customerRecordId=id;$('#wizard').hidden=true;$('#success').hidden=false;renderSuccess();updateCount();$('#quote').scrollIntoView({behavior:'smooth'});}
function renderSuccess(){
 const r=records.find(r=>r.id===customerRecordId);if(!r)return;
 $('#success').innerHTML=`<div class="success-icon">âœ“</div><span class="eyebrow dark">REQUEST ${r.id}</span><h2 style="margin-top:10px">Thanks, ${esc(firstName(r.job.name))}. We have your details.</h2><p class="muted">You can leave this page. Weâ€™ll review your move and send your quote by email${r.job.whatsapp?' and WhatsApp':''}.</p>${successSummary({...r,confirmed:null})}${enquiryOnly?'<p class="soft-note"><strong>Working preview.</strong> This enquiry stays in this browser tab. No real message has been sent.</p>':'<p class="soft-note"><strong>Working preview.</strong> Open Customer screens to see the acknowledgement and quote messages. No real message has been sent.</p><div class="quote-actions"><button class="button teal" id="previewAck">See customer messages â†—</button><button class="button outline" id="reviewDemo">Open owner desk</button></div>'}<button class="textbutton" id="newEnquiry" style="display:block;margin-top:12px">Start another enquiry</button>`;
 $('#previewAck')?.addEventListener('click',()=>openScreens(r.id,'email'));
 $('#reviewDemo')?.addEventListener('click',()=>{selectedId=r.id;goView(true);});
 $('#newEnquiry').onclick=newEnquiry;
}
function successSummary(r){const j=r.job;return `<div class="success-summary"><div><span>Collection</span><strong>${esc(j.from)}</strong></div><div><span>Delivery</span><strong>${esc(j.to)}</strong></div><div><span>Timing</span><strong>${esc(j.date||'Flexible date')}${j.flexible&&j.date?' Â· flexible':''}</strong></div><div><span>Collection help</span><strong>${labels.service[j.pickup.service]}</strong></div><div><span>Delivery help</span><strong>${labels.service[j.dropoff.service]}</strong></div>${r.confirmed?`<div><span>Agreed scope</span><strong>${esc(r.confirmed.scope)}</strong></div>`:''}</div>`;}
function newEnquiry(){job=blank();photos=[];step=0;customerRecordId=null;$('#wizard').hidden=false;$('#success').hidden=true;renderStep();goView(false);setTimeout(()=>$('#quote').scrollIntoView({behavior:'smooth'}),100);}
$('#blankForm').onclick=newEnquiry;
function updateCount(){$('#queueCount').textContent=records.length;$('#queueLabel').textContent=records.length+' in this tab';}
function renderQueue(){updateCount();$('#queueList').innerHTML=records.length?records.map(r=>`<button class="queue-item ${r.id===selectedId?'selected':''}" data-record="${r.id}"><strong>${esc(r.job.name||'New enquiry')}</strong><small>${r.id}${r.isSample?' Â· Sample job':''}<br>${esc(r.job.from)} â†’ ${esc(r.job.to)}</small><span class="badge ${r.confirmed?'ready':''}">${statusLabel(r)}</span></button>`).join(''):'<p class="muted" style="font-size:11px;padding:18px">Your test enquiries will appear here.</p>';document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.record;renderQueue();renderDetail();});}
function numControl(key,label,value,opts=''){return `<label class="field"><span class="field-label">${label}</span><input type="number" data-override="${key}" value="${value}" min="0" max="100000" step="any" ${opts}></label>`;}
function accessText(a){return labels.service[a.service]+(a.service==='indoor'?' Â· floor '+a.floor+(Number(a.floor)>0?' Â· '+(a.lift==='yes'?'suitable lift':a.lift==='no'?'stairs':'lift unknown'):''):'')+' Â· '+labels.carry[a.carry]+' Â· '+(a.steps==='none'?'no external steps':a.steps==='few'?'1â€“3 external steps':a.steps==='many'?'4+ external steps':'steps unknown')+(a.parking!=='yes'?' Â· parking to check':'')+(a.tight?' Â· tight access':'');}
function renderDetail(){const r=records.find(x=>x.id===selectedId);if(!r)return;const j=r.job,c=calculate(j,settings,r.overrides),o=c.overrides;$('#quoteDetail').innerHTML=`<div class="detail-top"><div><span class="eyebrow dark">${r.id}${r.isSample?' / SAMPLE ENQUIRY':''}</span><h2>${esc(j.name)}</h2><p>${esc([j.email,j.phone].filter(Boolean).join(' Â· '))||'Sample details'}</p></div><span class="badge ${r.confirmed?'ready':''}">${statusLabel(r)}</span></div><div class="detail-body"><div class="route-summary"><div><span>Collection</span><strong>${esc(j.from)}</strong></div><b style="color:var(--teal)">â†’</b><div><span>Delivery</span><strong>${esc(j.to)}</strong></div></div><p class="access-summary"><strong>Collection:</strong> ${accessText(j.pickup)}<br><strong>Delivery:</strong> ${accessText(j.dropoff)}</p>${j.stops.length?`<p class="access-summary"><strong>Extra stops:</strong> ${esc(j.stops.join(' Â· '))}</p>`:''}<div class="job-description">${esc(j.description)}</div><div class="detail-chips"><span>${labels.load[j.load]}</span><span>${labels.itemKind[j.itemKind]}</span><span>${esc(j.date||'Flexible date')}</span>${j.flexible?'<span>Date flexible</span>':''}${j.timing==='urgent'?'<span>Urgent / out of hours</span>':''}</div>${j.notes?`<p class="access-summary"><strong>Customer notes:</strong> ${esc(j.notes)}</p>`:''}<div class="attachments">${j.listing?`<a href="${esc(j.listing)}" target="_blank" rel="noopener noreferrer">Open item listing â†—</a>`:''}${r.photos.map(p=>`<a href="${p.url}" target="_blank" rel="noopener noreferrer">${esc(p.name)} â†—</a>`).join('')}</div><div id="changeReview"></div><div id="calculation"><div class="review-flags"><strong>CHECK BEFORE CONFIRMING</strong><ul id="flagList"></ul></div><div class="subhead">Plan the complete job <span>Editable estimates Â· minutes</span></div><p class="helper">These route times are illustrative, not calculated from Eircodes. Include every stop and return / onward travel. Normal local vehicle running costs are included in the hourly rate.</p><div class="controls-grid">${numControl('dispatch','Travel to collection',o.dispatch)}${numControl('travel','Driving between all stops',o.travel)}${numControl('returnTime','Return / onward travel',o.returnTime)}<label class="field"><span class="field-label">Crew / standard van</span><select data-override="crew"><option value="auto" ${o.crew==='auto'?'selected':''}>Suggested crew (${c.crew} people)</option><option value="1" ${o.crew==='1'?'selected':''}>One mover</option><option value="2" ${o.crew==='2'?'selected':''}>Two movers</option></select></label>${numControl('handlingAdjustment','Additional handling (minutes)',o.handlingAdjustment)}${j.assembly==='yes'?numControl('assembly','Dismantling / assembly (minutes)',o.assembly):''}${numControl('equipment','Equipment / materials (â‚¬ net)',o.equipment)}${numControl('expenses','Parking / tolls (â‚¬ net)',o.expenses)}${numControl('extraKm','Extra km outside local allowance',o.extraKm)}${numControl('kmRate','Extra running cost per km (â‚¬)',o.kmRate)}</div><p class="helper">Extra mileage is for incremental fuel and wear outside the local allowance. Travel time is already priced above. A larger truck or specialist crew needs a separate confirmed rate.</p><div class="subhead">Time & price breakdown <span>Round the total once to 15 minutes</span></div><table class="cost-table"><tbody id="costRows"></tbody></table><div class="price-strip"><div><small>Internal subtotal Â· before VAT</small><strong id="netPrice"></strong></div><div class="right"><small>Indicative customer total</small><strong id="grossPrice"></strong></div></div><p class="helper">Illustrative pricing only. Specialist handling and incomplete access may change the scope. Prepared quotes stay private. The customer only sees a price after the separate Send quote step.</p><div class="subhead">Review before preparing a quote</div><label class="check"><input type="checkbox" data-override="routeVerified" ${o.routeVerified?'checked':''}><span>I have verified all route times, locations and vehicle access.</span></label><label class="check"><input type="checkbox" data-override="handlingVerified" ${o.handlingVerified?'checked':''}><span>I have reviewed the items, quantities, capacity and handling time.</span></label><label class="check"><input type="checkbox" data-override="feasibility" ${o.feasibility?'checked':''}><span>I have resolved the review flags and confirmed suitable staff, equipment and availability.</span></label><label class="field"><span class="field-label">Agreed scope / quote notes</span><textarea id="scopeNote" maxlength="3000" placeholder="Confirm the items, service at each address, access assumptions and any agreed extras.">${esc(r.scope||'')}</textarea></label><div class="quote-actions"><button class="button teal" id="prepareQuote">Prepare quote draft â†—</button><button class="button outline" id="copyBreakdown">Copy breakdown</button><button class="textbutton" id="printQuote" ${r.confirmed?'':'hidden'}>Print demo quote</button></div><p id="approvalHint" class="helper"></p><div id="confirmedNote"></div><div id="deliveryControls"></div></div><div class="print-only" id="printContent"></div></div>`;
 $('#quoteDetail').querySelectorAll('[data-override]').forEach(el=>el.addEventListener('change',()=>{if(el.type==='number'&&(!Number.isFinite(Number(el.value))||Number(el.value)<0||Number(el.value)>100000)){el.value=c.overrides[el.dataset.override];return toast('Please use a non-negative number within range.');}r.overrides[el.dataset.override]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;invalidate(r);refreshCalc(r);}));
 $('#scopeNote').addEventListener('input',e=>{r.scope=e.target.value;invalidate(r);refreshCalc(r);});
 $('#prepareQuote').onclick=()=>confirmQuote(r);$('#copyBreakdown').onclick=()=>copyBreakdown(r);$('#printQuote').onclick=()=>{openScreens(r.id,'quote');window.print();};refreshCalc(r);
}
function invalidate(r){if(r.confirmed){r.confirmed=null;renderQueue();if(r.id===customerRecordId)renderSuccess();const badge=$('#quoteDetail .detail-top .badge');if(badge){badge.textContent=statusLabel(r);badge.classList.toggle('ready',!!r.sent);}}}
function refreshCalc(r){const c=calculate(r.job,settings,r.overrides);$('#flagList').innerHTML=c.flags.length?c.flags.map(f=>`<li>${esc(f)}</li>`).join(''):'<li>No extra automatic flags. Complete the final scope review.</li>';$('#costRows').innerHTML=c.rows.map(x=>`<tr><td>${esc(x.label)}</td><td>${x.minutes} min</td></tr>`).join('')+`<tr><td>Planned time</td><td>${c.rawMinutes} min</td></tr><tr><td>Priced time (${settings.minHours}h minimum, then 15-min blocks)</td><td>${c.billedMinutes} min</td></tr><tr><td>${c.crew} mover${c.crew>1?'s':''} & van Â· ${money(c.rate)}/hour</td><td>${money(c.labour)}</td></tr>${c.premium?`<tr><td>Urgent / out-of-hours premium (${settings.urgent}%)</td><td>${money(c.premium)}</td></tr>`:''}${c.extras?`<tr><td>Equipment, parking / tolls & extra running costs</td><td>${money(c.extras)}</td></tr>`:''}<tr><td>VAT (sample setting ${settings.vat}%)</td><td>${money(c.tax)}</td></tr><tr class="total"><td>Indicative total including VAT</td><td>${money(c.total)}</td></tr>`;$('#netPrice').textContent=money(c.net);$('#grossPrice').textContent=money(c.total);$('#prepareQuote').disabled=r.response==='changes_requested'||!c.eligible||!(r.scope?.trim());$('#approvalHint').textContent=c.eligible?(r.scope?.trim()?'Ready to prepare a demonstration quote. No message will be sent.':'Add the agreed scope to prepare the demo quote.'):'Complete all three review checks and confirm a suitable crew before preparing the demo quote.';$('#printQuote').hidden=!r.sent;$('#confirmedNote').innerHTML=r.confirmed?'<p class="soft-note">Draft prepared. Review the delivery options below, then send it in the demo. Preparing alone does not update the customerâ€™s quote.</p>':'';if(r.confirmed){const q=r.confirmed;$('#printContent').innerHTML=`<h2>VALET REMOVALS & TRANSPORT</h2><p>DEMONSTRATION QUOTE Â· ${r.id}</p><h3>${esc(r.job.name)}</h3><p>${esc(r.job.from)} â†’ ${esc(r.job.to)}</p><p>${esc(q.scope)}</p><p>Subtotal: ${money(q.net)}<br>VAT (${q.settings.vat}%): ${money(q.tax)}</p><h2>Total: ${money(q.total)}</h2><p>Price for the agreed scope. Additional items or changed requirements must be agreed before additional work begins.</p><p>Prototype only â€” no booking or payment has been made.</p>`;}renderDeliveryControls(r);renderChangeReview(r);if(r.response==='changes_requested')$('#approvalHint').textContent='Use the change-request approval panel above to prepare the revised price and scope.';}
function confirmQuote(r){if(r.response==='changes_requested')return toast('Approve the change request using the panel above.');const c=calculate(r.job,settings,r.overrides);if(!c.eligible||!r.scope?.trim())return;prepareDraft(r,{...c,scope:r.scope,settings:clone(settings),validUntil:futureDate(7),explanation:r.explanation||'',emailIntro:r.emailIntro||'',whatsappIntro:r.whatsappIntro||''});renderQueue();renderDetail();toast('Draft prepared privately. Review and send below.');}
async function copyBreakdown(r){const c=calculate(r.job,settings,r.overrides);const text=`VALET REMOVALS & TRANSPORT â€” INTERNAL DEMO\n${r.id}: ${r.job.from} â†’ ${r.job.to}\n${r.job.description}\n\n${c.rows.map(x=>x.label+': '+x.minutes+' min').join('\n')}\nPriced time: ${c.billedMinutes} min\nCrew: ${c.crew}\nSubtotal: ${money(c.net)}\nVAT: ${money(c.tax)}\nIndicative total: ${money(c.total)}\n\nReview: ${c.flags.join('; ')}\nNot a booking or a sent quotation.`;try{await navigator.clipboard.writeText(text);toast('Breakdown copied.');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Breakdown copied.':'Copy is unavailable in this browser. Use the on-screen breakdown.');}}
const settingLabels={one:'One mover + van (â‚¬ / hour)',two:'Two movers + van (â‚¬ / hour)',minHours:'Minimum booking (hours)',vat:'VAT setting (%)',small:'Small load handling / address (min)',medium:'Part van handling / address (min)',large:'Full van handling / address (min)',stairs:'Stairs / floor, small load (min)',lift:'Lift allowance, small load (min)',carryMid:'10â€“30m carry, small load (min)',carryLong:'30â€“50m carry, small load (min)',steps:'1â€“3 external steps (min)',extraStop:'Extra stop handling (min)',urgent:'Urgent / out-of-hours premium (%)',waitGrace:'Waiting grace period (min)'};
function renderSettings(){$('#settingsPanel').innerHTML=`<h2>Make the model fit your costs.</h2><p>All rates are illustrative. Hourly figures exclude VAT and include normal local vehicle running costs. Confirm your VAT treatment before launch. Larger loads scale access time: small Ã—1, part van Ã—1.5, full van Ã—2.5.</p><div class="settings-grid">${Object.keys(DEFAULTS).map(k=>`<label class="field"><span class="field-label">${settingLabels[k]}</span><input type="number" data-setting="${k}" value="${settings[k]}" min="0" max="10000" step="any"></label>`).join('')}</div><p>Waiting beyond ${settings.waitGrace} minutes would be charged at the agreed crew rate in 15-minute blocks, only for additional customer-caused delay. It is not added to these fixed-quote estimates.</p><button class="button small teal" id="saveSettings">Save model settings</button> <button class="textbutton" id="resetSettings">Restore sample rates</button><p class="helper">Only rate settings are saved on this device. Enquiries and photos are not saved after this tab closes.</p>`;$('#saveSettings').onclick=()=>{const next={};let valid=true;$('#settingsPanel').querySelectorAll('[data-setting]').forEach(e=>{const n=Number(e.value);if(e.value===''||!Number.isFinite(n)||n<0||n>10000)valid=false;next[e.dataset.setting]=n;});if(next.one<=0||next.two<=0||next.minHours<=0||next.vat>100||next.urgent>100)valid=false;if(!valid)return toast('Check your rates: positive hourly rates and minimum; percentages from 0 to 100.');settings=next;saveSettings();};$('#resetSettings').onclick=()=>{settings={...DEFAULTS};saveSettings();};}
function saveSettings(){let persisted=true;try{localStorage.setItem('valet-rates-v1',JSON.stringify(settings));}catch{persisted=false;}records.forEach(r=>invalidate(r));renderSettings();renderDetail();toast(persisted?'Rates saved. Existing demo quotes need review.':'Rates applied for this tab; browser storage is unavailable.');}
