let previewRecordId=null,previewScreen='email',previewStage='quote',customerPanel='',quoteEntryChannel='quote';
function futureDate(days){const d=new Date();d.setDate(d.getDate()+days);return d.toLocaleDateString('en-CA',{timeZone:'Europe/Dublin'});}
function firstName(name){return String(name||'there').trim().split(/\s+/)[0];}
function niceDate(value){return value?new Date(value+'T12:00:00').toLocaleDateString('en-IE',{day:'numeric',month:'long',year:'numeric'}):'Date to be agreed';}
function timeLabel(value){return new Date(value||Date.now()).toLocaleTimeString('en-IE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Dublin'});}
function miniBrand(){return `<svg width="35" height="35" viewBox="0 0 40 40" aria-hidden="true"><path d="M20 3L36 12.2L20 21.4L4 12.2Z" fill="#00D1D1"/><path d="M36 12.2V27.8L20 37V21.4Z" fill="#00A8A8"/><path d="M4 12.2L20 21.4V37L4 27.8Z" fill="#EE6425"/></svg><span><b>VALET</b><small>REMOVALS & TRANSPORT</small></span>`;}
function currentPreview(){return records.find(r=>r.id===previewRecordId);}
function deliveryChanged(r){renderQueue();if(!$('#ownerView').hidden&&r.id===selectedId)renderDetail();if(customerRecordId===r.id)renderSuccess();}

