function showSendDialog(r){
 const q=r.confirmed,channels=r.deliveryChoices;
 if(!q)return;
 if(!channels.email&&!channels.whatsapp)return toast('Choose email or WhatsApp before sending.');
 if(!q.validUntil||q.validUntil<futureDate(0))return toast('Choose a current or future quote expiry date.');
 $('#sendDialog')?.remove();
 const d=document.createElement('dialog');d.id='sendDialog';d.className='send-dialog';
 d.innerHTML=`<div class="dialog-inner"><button class="dialog-close" aria-label="Close">Ã—</button><span class="eyebrow dark">FINAL CHECK Â· REVISION ${q.revision}</span><h2>Ready to send this quote?</h2><p>${esc(r.job.name)} Â· ${r.id}</p><div class="draft-overview"><span>Total including VAT</span><strong>${money(q.total)}</strong></div><div class="dialog-channels">${channels.email?`<div><strong>Email</strong> Â· ${esc(r.job.email)}</div>`:''}${channels.whatsapp?`<div><strong>WhatsApp</strong> Â· ${esc(r.job.phone)}</div>`:''}</div>${q.change?changeSummary(q):''}<p class="customer-scope">${esc(q.scope)}</p><p class="helper">Valid until ${niceDate(q.validUntil)}. The customer will be able to ask a question, request a change or accept.</p><p class="soft-note"><strong>Simulation only.</strong> This creates working message previews. It does not send a real email or WhatsApp message.</p><div class="quote-actions"><button class="button outline" id="cancelSend">Keep editing</button><button class="button orange" id="sendNow">Send quote in demo â†—</button></div></div>`;
 document.body.append(d);d.querySelector('.dialog-close').onclick=()=>d.close();$('#cancelSend').onclick=()=>d.close();
 $('#sendNow').onclick=()=>{try{sendDraft(r,channels);d.close();d.remove();deliveryChanged(r);openScreens(r.id,channels.whatsapp?'whatsapp':'email','quote');toast('Quote sent in the model. These are the customerâ€™s screens.');}catch(e){toast(e.message);}};
 d.showModal();
}

function fullJourney(){
 if(enquiryOnly)return;
 const j=blank();Object.assign(j,{name:'Alex Murphy',email:'alex@example.com',phone:'+353 00 000 0000',whatsapp:true,from:'Ranelagh, Dublin 6',to:'DÃºn Laoghaire, Co. Dublin',date:futureDate(3),load:'medium',itemKind:'bulky',description:'A 3-seater sofa, a dismantled double bed and 12 packed boxes.',acknowledge:true});j.pickup={...access(),service:'indoor',floor:'2',lift:'no',carry:'mid'};j.dropoff={...access(),service:'indoor'};
 const id='VLT-'+String(records.length+1).padStart(3,'0');
 const r={id,job:j,photos:[],overrides:{dispatch:20,travel:30,returnTime:20,routeVerified:true,handlingVerified:true,feasibility:true},confirmed:null,isSample:true,isJourney:true,scope:'Collection of one 3-seater sofa, one dismantled double bed and 12 packed boxes from the second floor without a lift. Two movers and a standard van. Loading, protective securing, transport and ground-floor indoor delivery are included. Items to be packed and ready. No reassembly included.',explanation:'This quote includes two movers and the extra carrying time from the second floor to the van. If you can have everything safely ready at ground level before we arrive, ask us to review the price.'};
 records.unshift(r);selectedId=id;customerRecordId=id;
 prepareDraft(r,{...calculate(j,settings,r.overrides),scope:r.scope,settings:clone(settings),validUntil:futureDate(7),explanation:r.explanation});
 sendDraft(r,{email:true,whatsapp:true});
 $('#wizard').hidden=true;$('#success').hidden=false;renderSuccess();updateCount();openScreens(id,'whatsapp','quote');
}
$('#fullJourneyBtn').onclick=fullJourney;
